builder.Services
    .AddGraphQLServer()
    .ModifyRequestOptions(opt =>
    {
        opt.ComplexityLimit = 100;
    })
    .AddQueryType<Query>()
    .AddType<BookType>();

// Set field complexity on types
public class BookType : ObjectType<Book>
{
    protected override void Configure(IObjectTypeDescriptor<Book> d)
    {
        d.Field(b => b.Author).Complexity(10);
        d.Field(b => b.Reviews).Complexity(20);
    }
}

query {
  getBooks {
    title
    author { name bio }
    reviews { rating comment }
  }
}
